### Создание простейшего приложения



Определим простейшее приложение на GLFW:



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>

int main() {
    glfwInit();  // Инициализация GLFW

    // Отключим создание контекста
    glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
    // Создание окна
    GLFWwindow* window = glfwCreateWindow(800, 600, "enoobis.ru", nullptr, nullptr);

    // Жизненный цикл
    while(!glfwWindowShouldClose(window)) {
        // Обработка событий
        glfwWaitEvents();
    }

    // Уничтожение окна
    glfwDestroyWindow(window);

    // Завершение работы с GLFW
    glfwTerminate();

    return 0;
}
```



Прежде всего, подключаем необходимые заголовки



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>
```



Строка `#define GLFW_INCLUDE_VULKAN` позволяет добавить заголовки Vulkan вместо подключения стандартного заголовока Vulkan:



```cpp

#include <vulkan/vulkan.h>
```



Хотя мы могли бы также подключить данный заголовок. Причем это делается перед подключением заголовка библиотеки "GLFW/glfw3.h"



В функции main, чтобы использовать функционал GLFW, сначала надо провести инициализацию:



```cpp
glfwInit();
```



Далее отключаем создание контекста для OpenGL:



```cpp
glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
```



Vulkan не имеет контекста, а экземпляр Vulkan создается через сам API Vulkan. Поэтому при использовании в оконном приложении рендеринга Vulkan, нужно отключить создание контекста, установив для параметра GLFW_CLIENT_API значение GLFW_NO_API.



Далее собственно создается окно с помощью функции `glfwCreateWindow()`:



```cpp
GLFWwindow* window = glfwCreateWindow(800, 600, "enoobis.ru", nullptr, nullptr);
```



При создании окна в функцию `glfwCreateWindow()` передаются ширина, высота окна, текст заголовка. Последние два параметра - монитор для использования в полноэкранном режиме и окно для буферов ресурсами в данном случае не нужны, поэтому им передается null.



Затем в цикле с помощью функции `glfwWindowShouldClose()` проверяем, пришел ли для окна сигнал закрытия от системы. Внутри этого цикла обрабытавем события системы с помощью функции `glfwWaitEvents`.



```cpp

while(!glfwWindowShouldClose(window)) {
    glfwWaitEvents();
}
```



Выход из цикла означает, что получен сигнал на закрытие окна, и нам надо уничтожить окно. Для этого вызывается функция `glfwDestroyWindow()`. А для завершения работы с библиотекой GLFW вызовается функция `glfwTerminate()`



```cpp

glfwDestroyWindow(window);
glfwTerminate();
```




При запуске проекта на Windows отобразится пустое окно:



![первое приложение на glfw на c++ в windows](/uploads/course-lectures/35870e3ca2afb1fc489096c079fc7bd1bcaca0bb.png)



С Linux ситуация немного сложнее - вполне возможно на данном этапе отобразится окно, которое копирует содержимое верхнего левого угла, где появляется это окно по умолчанию:



![первое приложение на glfw на c++ на linux](/uploads/course-lectures/c717da95e3966e767cf518c2119488243b9d18fa.png)



Но это нормально, поскольку у нас пока нет никакой отрисовки.






### Расширения GLFW для Vulkan



GLFW имеет удобную встроенную функцию **glfwGetRequiredInstanceExtensions()** которая возвращает необходимые расширения для Vulkan:



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>
#include <iostream>

int main() {
    glfwInit();  // Инициализация GLFW

    // Отключим создание контекста
    glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
    // Создание окна
    GLFWwindow* window = glfwCreateWindow(800, 600, "enoobis.ru", nullptr, nullptr);
    
    uint32_t glfwExtensionCount = 0;
    const char** glfwExtensions;

    VkInstanceCreateInfo createInfo{};
    createInfo.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
    // получаем расширения для GLFW
    glfwExtensions = glfwGetRequiredInstanceExtensions(&glfwExtensionCount);
    // устанавливаем расширения для VkInstance
    createInfo.enabledExtensionCount = glfwExtensionCount;
    createInfo.ppEnabledExtensionNames = glfwExtensions;

    std::cout << glfwExtensionCount << " расширений доступно\n";

    // Жизненный цикл
    while(!glfwWindowShouldClose(window)) {
        // Обработка событий
        glfwWaitEvents();
    }

    // Уничтожение окна
    glfwDestroyWindow(window);

    // Завершение работы с GLFW
    glfwTerminate();

    return 0;
}
```



### Структура приложения



В дальнейшем мы будем придерживаться следующей структуры:



```brutecpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>
#include <cstdlib>
#include <stdexcept>
#include <iostream>

// размеры окна
const uint32_t WIDTH = 300;
const uint32_t HEIGHT = 250;

// структура приложения
class HelloApplication {
public:
    void run() {
        initWindow();   // инициализация окна GLFW
        initVulkan();   // инициализация Vulkan
        mainLoop();     // цикл приложения
        cleanup();      // удаление используемых ресурсов
    }

private:
    GLFWwindow* window;

    // создаем окно
    void initWindow() {
        glfwInit();     // инициализация GLFW   

        glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_FALSE);
        window = glfwCreateWindow(WIDTH, HEIGHT, "enoobis.ru", nullptr, nullptr);
    }
    // инициализация всех аспектов Vulkan
    void initVulkan() {
        
    }
    // основной цикл программы, где прослушиваем пользовательские события
    void mainLoop() {
        while (!glfwWindowShouldClose(window)) {
            glfwWaitEvents();
        }
    }
    // удаление ресурсов
    void cleanup() {

        glfwDestroyWindow(window);  // удаляем окно
        glfwTerminate();
    }
};

int main() {
    HelloApplication app;

    try {
        app.run();
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```



Основной код оборачивается в класс HelloApplication, где различные этапы приложения последовательно запускаются в метое `run()`:





- initWindow() : здесь создается окно GLFW и выполняются все аспекты, связанные с настройкой окна

- initVulkan() : здесь будет производиться инициализация всех аспектов, связанных с Vulkan. В примере выше эта функция пустая, но в дальнейшем сюда будет добавлено много функциональности, как получение устройств, создание графического конвейера, отрисовка и т.д.

- mainLoop() : здесь в цикле будем прослушивать пользовательские события окна

- cleanup() : здесь будет выполняться очистка всех созданных ресурсов. Так, в примере выше в этой функции происходит удаление ранее созданного окна.



В функции main в конструкции `try..catch` запускаем метод run класса HelloApplication. Использование `try..catch` позволит упростить будущую обработку ошибок.



Чтобы было представление применения данной структуры, добавим в него создание объекта `VkInstance`:



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>
#include <cstdlib>
#include <stdexcept>
#include <iostream>

// размеры окна
const uint32_t WIDTH = 300;
const uint32_t HEIGHT = 250;

// структура приложения
class HelloApplication {
public:
    void run() {
        initWindow();   // инициализация окна GLFW
        initVulkan();   // инициализация Vulkan
        mainLoop();     // цикл приложения
        cleanup();      // удаление используемых ресурсов
    }

private:
    GLFWwindow* window;
    VkInstance instance; 

    // создаем окно
    void initWindow() {
        glfwInit();     // инициализация GLFW   
        glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_FALSE);
        window = glfwCreateWindow(WIDTH, HEIGHT, "enoobis.ru", nullptr, nullptr);
    }
    // инициализация всех аспектов Vulkan
    void initVulkan() {
        createInstance();           // создание VkInstance
    }
    void mainLoop() {
        while (!glfwWindowShouldClose(window)) {
            glfwWaitEvents();
        }
    }
    // удаление ресурсов
    void cleanup() {
        
        vkDestroyInstance(instance, nullptr); // удаляем объект VkInstance
        glfwDestroyWindow(window);  // удаляем окно
        glfwTerminate();
    }

        // создание VkInstance
    void createInstance() {

        VkInstanceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;

        uint32_t glfwExtensionCount = 0;
        const char** glfwExtensions;
        // получаем расширения для GLFW
        glfwExtensions = glfwGetRequiredInstanceExtensions(&glfwExtensionCount);
        // устанавливаем расширения для VkInstance
        createInfo.enabledExtensionCount = glfwExtensionCount;
        createInfo.ppEnabledExtensionNames = glfwExtensions;

        if (vkCreateInstance(&createInfo, nullptr, &instance) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать VkInstance!");
        }
    }
};

int main() {
    HelloApplication app;

    try {
        app.run();
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```



Здесь на уровне класса определяется приватная переменная типа VkInstance для использования этого объекта в будущих операциях. Создание этого объекта вынесено в отдельную функцию - createInstance, которая вызывается в функции `initVulkan()`, специально предназначеной для инициализации различных аспектов Vulkan. После завершения работы нам надо удалить VkInstance, и это делается в функции cleanup. Такая структура упростить общее понимание приложения, и в дальнейшем мы будем придерживаться ее.

Рассмотрим получение поверхности рисования в приложении на GLFW:

```cpp
#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>

#include <iostream>
#include <stdexcept>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <set>

// размеры окна
const uint32_t WIDTH = 300;
const uint32_t HEIGHT = 250;

// структура для хранения индекса семейства графичесой очереди
struct QueueFamilyIndex {
    uint32_t graphicsFamilyIndex;  // сам индекс 
    VkBool32 graphicsSupport;       // есть ли поддержка графической очереди на устройстве
};

class HelloApplication {
public:
    void run() {
        initWindow();
        initVulkan();
        mainLoop();
        cleanup();
    }

private:
    GLFWwindow* window;

    VkInstance instance;
    VkSurfaceKHR surface;       // поверхность рисования

    VkPhysicalDevice physicalDevice = VK_NULL_HANDLE; // физическое устройство
    VkDevice device;        // логическое устройство

    VkQueue graphicsQueue;  // графическая очередь

    // создаем окно
    void initWindow() {
        glfwInit();

        glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_FALSE);
        window = glfwCreateWindow(WIDTH, HEIGHT, "enoobis.ru", nullptr, nullptr);
    }
    // инициализация всех аспектов Vulkan
    void initVulkan() {
        createInstance();           // создание VkInstance
        createSurface();            // создание поверхности рисования
        selectPhysicalDevice();     // выбор физического устройства
        createLogicalDevice();      // создание логического устройства
    }

    void mainLoop() {
        while (!glfwWindowShouldClose(window)) {
            glfwWaitEvents();
        }
    }

    void cleanup() {
        // удаляем логическое устройство
        vkDestroyDevice(device, nullptr);
        // удаляем поверхность
        vkDestroySurfaceKHR(instance, surface, nullptr);
        // удаляем объект VkInstance
        vkDestroyInstance(instance, nullptr);

        glfwDestroyWindow(window);
        glfwTerminate();
    }

    // создание VkInstance
    void createInstance() {

        VkInstanceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;

        uint32_t glfwExtensionCount = 0;
        const char** glfwExtensions;
        // получаем расширения для GLFW
        glfwExtensions = glfwGetRequiredInstanceExtensions(&glfwExtensionCount);
        // устанавливаем расширения для VkInstance
        createInfo.enabledExtensionCount = glfwExtensionCount;
        createInfo.ppEnabledExtensionNames = glfwExtensions;

        if (vkCreateInstance(&createInfo, nullptr, &instance) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать VkInstance!");
        }
    }

    // создаем поверхность
    void createSurface() {
        if (glfwCreateWindowSurface(instance, window, nullptr, &surface) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать поверхность окна!");
        }
    }
    // выбираем физическое устройство
    void selectPhysicalDevice() {
        uint32_t deviceCount = 0;
        vkEnumeratePhysicalDevices(instance, &deviceCount, nullptr);

        if (deviceCount == 0) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }

        std::vector<VkPhysicalDevice> devices(deviceCount);
        vkEnumeratePhysicalDevices(instance, &deviceCount, devices.data());

        // выбираем первое подходящее устройство
        for (const auto& device : devices) {
            if (isDeviceSuitable(device)) {
                physicalDevice = device;
                break;
            }
        }

        if (physicalDevice == VK_NULL_HANDLE) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }
    }
    // создание логического устройства
    void createLogicalDevice() {
        // получаем индекс графической очереди
        QueueFamilyIndex index = findQueueFamily(physicalDevice);
        if (index.graphicsSupport == false) {
            throw std::runtime_error("Графическая очередь не поддерживается");
        }

        float queuePriority = 1.0f;  // Приоритет очереди
        VkDeviceQueueCreateInfo queueCreateInfo{};
        queueCreateInfo.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
        queueCreateInfo.queueFamilyIndex = index.graphicsFamilyIndex; // Индекс семейства графических очередей
        queueCreateInfo.queueCount = 1;   // Нам нужна 1 очередь из этого семейства
        queueCreateInfo.pQueuePriorities = &queuePriority;

        VkDeviceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;

        createInfo.queueCreateInfoCount = 1;
        createInfo.pQueueCreateInfos = &queueCreateInfo;
        createInfo.enabledExtensionCount = 0;

        // создаем логическое устройство
        if (vkCreateDevice(physicalDevice, &createInfo, nullptr, &device) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать логическое устройство!");
        }
        // создаем графическую очередь
        vkGetDeviceQueue(device, index.graphicsFamilyIndex, 0, &graphicsQueue);
    }

    // проверка, является ли устройство подходящим
    bool isDeviceSuitable(VkPhysicalDevice device) {
        QueueFamilyIndex index = findQueueFamily(device);
        // считаем устройство подходящим, если есть поддержка графической очереди
        return index.graphicsSupport;
    }

    // получаем индекс семейства очередей
    QueueFamilyIndex findQueueFamily(VkPhysicalDevice device) {
        QueueFamilyIndex index;
        index.graphicsSupport = false;

        uint32_t queueFamilyCount = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, nullptr);

        std::vector<VkQueueFamilyProperties> queueFamilies(queueFamilyCount);
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, queueFamilies.data());

        int i = 0;
        for (const auto& queueFamily : queueFamilies) {
            // получаем графическую очередь
            if (queueFamily.queueFlags & VK_QUEUE_GRAPHICS_BIT) {
                index.graphicsFamilyIndex = i;
                index.graphicsSupport = true;
                break;
            }
            i++;
        }
        return index;
    }
};

int main() {
    HelloApplication app;

    try {
        app.run();
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

Здесь не так много кода, связанного с поверхностью рисования. Прежде всего для хранения поверхности рисования в классе HelloApplication определена переменная surface, которая представляет указатель **VkSurfaceKHR**:

```cpp
VkSurfaceKHR surface;
```

Само создание поверхности происходит в функции `createSurface()`, которая устанавливает переменную surface:

```cpp
void createSurface() {
    if (glfwCreateWindowSurface(instance, window, nullptr, &surface) != VK_SUCCESS) {
        throw std::runtime_error("Не удалось создать поверхность окна!");
    }
}
```

В GLFW для создания поверхности рисования применяется функция **glfwCreateWindowSurface()**, которая позволяет абстрагироваться от конкретной платформы и позволяет:

```c
VkResult glfwCreateWindowSurface (VkInstance instance, GLFWwindow *window, const VkAllocationCallbacks *allocator, VkSurfaceKHR *surface)
```

В качестве параметров функция принимает объект VkInstance, указатель окна GLFW, распределитель памяти и указатель на переменную **VkSurfaceKHR**, через которую возвращается созданная поверхность. На уровне конкретной операционной системы эта функция в реальности обращается к функции, которая характерна для текущей системы. Например, для Windows это будет функция **vkCreateWin32SurfaceKHR()**, которая возвращает поверхность для окна в Windows

Получив поверхность рисования, далее мы сможем использовать эту переменную для отрисовки графики.

Продолжим работу с приложением на GLFW из прошлой темы и рассмотрим получение в нем очереди представления:



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>

#include <iostream>
#include <stdexcept>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <set>

const uint32_t WIDTH = 300;
const uint32_t HEIGHT = 250;

// структура для хранения индексов семейств очередей
struct QueueFamilyIndices {
    uint32_t graphicsFamilyIndex;
    uint32_t presentFamilyIndex;

    VkBool32 graphicsSupport;
    VkBool32 presentSupport;

    bool isComplete() {
        return graphicsSupport && presentSupport;
    }
};

class HelloApplication {
public:
    void run() {
        initWindow();
        initVulkan();
        mainLoop();
        cleanup();
    }

private:
    GLFWwindow* window;

    VkInstance instance;
    VkSurfaceKHR surface;       // поверхность рисования

    // физическое устройство
    VkPhysicalDevice physicalDevice = VK_NULL_HANDLE;
    // логическре устройство
    VkDevice device;

    VkQueue graphicsQueue;  // графическая очередь
    VkQueue presentQueue;   // очередь представления

    // создаем окно
    void initWindow() {
        glfwInit();

        glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_FALSE);
        window = glfwCreateWindow(WIDTH, HEIGHT, "enoobis.ru", nullptr, nullptr);
    }

    // инициализация всех аспектов Vulkan
    void initVulkan() {
        createInstance();           // создание VkInstance
        createSurface();            // создание поверхности рисования
        selectPhysicalDevice();     // выбор физического устройства
        createLogicalDevice();      // создание логического устройства
    }

    void mainLoop() {
        while (!glfwWindowShouldClose(window)) {
            glfwWaitEvents();
        }
    }

    void cleanup() {
        // удаляем логическое устройство
        vkDestroyDevice(device, nullptr);
        // удаляем поверхность
        vkDestroySurfaceKHR(instance, surface, nullptr);
        // удаляем объект VkInstance
        vkDestroyInstance(instance, nullptr);

        glfwDestroyWindow(window);
        glfwTerminate();
    }

    // создание VkInstance
    void createInstance() {

        VkInstanceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;

        uint32_t glfwExtensionCount = 0;
        const char** glfwExtensions;
        // получаем расширения для GLFW
        glfwExtensions = glfwGetRequiredInstanceExtensions(&glfwExtensionCount);
        // устанавливаем расширения для VkInstance
        createInfo.enabledExtensionCount = glfwExtensionCount;
        createInfo.ppEnabledExtensionNames = glfwExtensions;

        if (vkCreateInstance(&createInfo, nullptr, &instance) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать VkInstance!");
        }
    }

    // создаем поверхность
    void createSurface() {
        if (glfwCreateWindowSurface(instance, window, nullptr, &surface) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать поверхность для рисования!");
        }
    }

    // выбираем физическое устройство
    void selectPhysicalDevice() {
        uint32_t deviceCount = 0;
        vkEnumeratePhysicalDevices(instance, &deviceCount, nullptr);

        if (deviceCount == 0) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }

        std::vector<VkPhysicalDevice> devices(deviceCount);
        vkEnumeratePhysicalDevices(instance, &deviceCount, devices.data());

        // выбираем первое подходящее устройство
        for (const auto& device : devices) {
            if (isDeviceSuitable(device)) {
                physicalDevice = device;
                break;
            }
        }

        if (physicalDevice == VK_NULL_HANDLE) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }
    }

    // создание логического устройства
    void createLogicalDevice() {
        // получаем обе очереди
        QueueFamilyIndices indices = findQueueFamilies(physicalDevice);

        std::vector<VkDeviceQueueCreateInfo> queueCreateInfos;
        // набор для индексов семейств очередей, если они совпадают, то остается только один индекс
        std::set<uint32_t> uniqueQueueFamilies = {
            indices.graphicsFamilyIndex,
            indices.presentFamilyIndex
        };

        float queuePriority = 1.0f;
        // проходим по всем индексам семейств очередей и создаем для каждого индекса структуру VkDeviceQueueCreateInfo
        for (uint32_t queueFamily : uniqueQueueFamilies) {
            VkDeviceQueueCreateInfo queueCreateInfo{};
            queueCreateInfo.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
            queueCreateInfo.queueFamilyIndex = queueFamily;
            queueCreateInfo.queueCount = 1;
            queueCreateInfo.pQueuePriorities = &queuePriority;
            queueCreateInfos.push_back(queueCreateInfo);
        }

        VkDeviceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;

        // устанавливаем обе очереди для создания устройства
        createInfo.queueCreateInfoCount = static_cast<uint32_t>(queueCreateInfos.size());
        createInfo.pQueueCreateInfos = queueCreateInfos.data();
        createInfo.enabledExtensionCount = 0;

        // создаем логическое устройство
        if (vkCreateDevice(physicalDevice, &createInfo, nullptr, &device) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать логическое устройство!");
        }

        // создаем графическую очередь
        vkGetDeviceQueue(device, indices.graphicsFamilyIndex, 0, &graphicsQueue);
        // создаем очередь представления
        vkGetDeviceQueue(device, indices.presentFamilyIndex, 0, &presentQueue);
    }

   // проверка, является ли устройство подходящим
    bool isDeviceSuitable(VkPhysicalDevice device) {
        QueueFamilyIndices indices = findQueueFamilies(device);
        // считаем устройство подходящим, если есть поддержка обеих очередей
        return indices.isComplete();
    }
    // получаем индексы семейства очередей
    QueueFamilyIndices findQueueFamilies(VkPhysicalDevice device) {
        QueueFamilyIndices indices;

        uint32_t queueFamilyCount = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, nullptr);

        std::vector<VkQueueFamilyProperties> queueFamilies(queueFamilyCount);
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, queueFamilies.data());

        int i = 0;
        // проходим по всем очередям
        for (const auto& queueFamily : queueFamilies) {
            // получаем индекс семейства с графической очередью
            if (queueFamily.queueFlags & VK_QUEUE_GRAPHICS_BIT) {
                indices.graphicsFamilyIndex = i;
                indices.graphicsSupport = true;
            }
            // смотрим, поддерживается ли очередь представления
            vkGetPhysicalDeviceSurfaceSupportKHR(device, i, surface, &indices.presentSupport);
            if (indices.presentSupport)  indices.presentFamilyIndex = i;
            if (indices.isComplete())  break; // если обе очереди установлены
            i++;
        }
        return indices;
    }
};

int main() {
    HelloApplication app;

    try {
        app.run();
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```



Рассмотрим основные моменты, связанные с получением очереди представления. Прежде всего определяем структуру для хранения обоих индексов - индексов семейства очереди представления и семейства графической очереди (хотя, как правило, эти индексы совпадают, но ориентируемся на худший вариант):



```cpp

struct QueueFamilyIndices {
    uint32_t graphicsFamilyIndex;
    uint32_t presentFamilyIndex;

    VkBool32 graphicsSupport;
    VkBool32 presentSupport;

    bool isComplete() {
        return graphicsSupport && presentSupport;
    }
};
```



В нашем случае устройство должно поддерживать и графическую очередь, и очередь представления. А с помощью функции `isComplete()` мы сможем узнать, есть ли поддержка обоих очередей.



В основном классе программы для хранения очереди представления определена отдельная переменная:



```cpp
VkQueue presentQueue;
```




В функции `findQueueFamilies()` формируем структуру QueueFamilyIndices, получая индексы для семейств обеих очередей:



```cpp

for (const auto& queueFamily : queueFamilies) {
    // получаем индекс семейства с графической очередью
    if (queueFamily.queueFlags & VK_QUEUE_GRAPHICS_BIT) {
        indices.graphicsFamilyIndex = i;
        indices.graphicsSupport = true;
    }
    // смотрим, поддерживается ли очередь представления
    vkGetPhysicalDeviceSurfaceSupportKHR(device, i, surface, &indices.presentSupport);
    if (indices.presentSupport)  indices.presentFamilyIndex = i;
    if (indices.isComplete())  break; // если обе очереди установлены
    i++;
}
```



Для выявления поддержки очереди представления здесь применяется функция `vkGetPhysicalDeviceSurfaceSupportKHR()`



В функции `selectPhysicalDevice()` при выборе физического устройства выбираем первое попавшееся устройство, если оно поддерживает обе очереди.



В функции `createLogicalDevice()` при создании логического устройства получаем индексы семейств обоих очередей и определяем множество из них:



```cpp

std::set<uint32_t> uniqueQueueFamilies = {
    indices.graphicsFamilyIndex,
    indices.presentFamilyIndex
};
```



Благодаря этому, если оба индекса совпадают (что часто и происходит), то в наборе будет только один индекс.



Затем проходим по этому набору и для каждого индекса создаем структуру `VkDeviceQueueCreateInfo`



```cpp

std::vector<VkDeviceQueueCreateInfo> queueCreateInfos;

for (uint32_t queueFamily : uniqueQueueFamilies) {
    VkDeviceQueueCreateInfo queueCreateInfo{};
    queueCreateInfo.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
    queueCreateInfo.queueFamilyIndex = queueFamily;
    queueCreateInfo.queueCount = 1;
    queueCreateInfo.pQueuePriorities = &queuePriority;
    queueCreateInfos.push_back(queueCreateInfo);
}
```



В конце создаем обе очереди:



```cpp

vkGetDeviceQueue(device, indices.graphicsFamilyIndex, 0, &graphicsQueue);
vkGetDeviceQueue(device, indices.presentFamilyIndex, 0, &presentQueue);
```

Продолжим работу с приложением на GLFW из прошлой темы и рассмотрим проверку возможностей поверхности, получения доступных форматов, режимов представления:



```cpp

#define GLFW_INCLUDE_VULKAN
#include <GLFW/glfw3.h>

#include <iostream>
#include <stdexcept>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <set>

const uint32_t WIDTH = 300;
const uint32_t HEIGHT = 250;

// структура для проверки возможностей поверхности
struct SwapChainSupportDetails {
    VkSurfaceCapabilitiesKHR capabilities;              // возможности поверхности
    std::vector<VkSurfaceFormatKHR> formats;      // доступные форматы
    std::vector<VkPresentModeKHR> presentModes;   // доступные режимы представления
};

// структура для хранения индексов семейств очередей
struct QueueFamilyIndices {
    uint32_t graphicsFamilyIndex;
    uint32_t presentFamilyIndex;

    VkBool32 graphicsSupport;
    VkBool32 presentSupport;

    bool isComplete() {
        return graphicsSupport && presentSupport;
    }
};


class HelloApplication {
public:
    void run() {
        initWindow();
        initVulkan();
        mainLoop();
        cleanup();
    }

private:
    GLFWwindow* window;

    VkInstance instance;
    VkSurfaceKHR surface;       // поверхность рисования

    // физическое устройство
    VkPhysicalDevice physicalDevice = VK_NULL_HANDLE;
    // логическре устройство
    VkDevice device;

    VkQueue graphicsQueue;  // графическая очередь
    VkQueue presentQueue;   // очередь представления

    // создаем окно
    void initWindow() {
        glfwInit();

        glfwWindowHint(GLFW_CLIENT_API, GLFW_NO_API);
        glfwWindowHint(GLFW_RESIZABLE, GLFW_FALSE);
        window = glfwCreateWindow(WIDTH, HEIGHT, "enoobis.ru", nullptr, nullptr);
    }

    // инициализация всех аспектов Vulkan
    void initVulkan() {
        createInstance();           // создание VkInstance
        createSurface();            // создание поверхности рисования
        selectPhysicalDevice();     // выбор физического устройства
        createLogicalDevice();      // создание логического устройства
    }

    void mainLoop() {
        while (!glfwWindowShouldClose(window)) {
            glfwWaitEvents();
        }
    }

    void cleanup() {
        // удаляем логическое устройство
        vkDestroyDevice(device, nullptr);
        // удаляем поверхность
        vkDestroySurfaceKHR(instance, surface, nullptr);
        // удаляем объект VkInstance
        vkDestroyInstance(instance, nullptr);

        glfwDestroyWindow(window);
        glfwTerminate();
    }

    // создание VkInstance
    void createInstance() {

        VkInstanceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;

        uint32_t glfwExtensionCount = 0;
        const char** glfwExtensions;
        // получаем расширения для GLFW
        glfwExtensions = glfwGetRequiredInstanceExtensions(&glfwExtensionCount);
        // устанавливаем расширения для VkInstance
        createInfo.enabledExtensionCount = glfwExtensionCount;
        createInfo.ppEnabledExtensionNames = glfwExtensions;

        if (vkCreateInstance(&createInfo, nullptr, &instance) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать VkInstance!");
        }
    }

    // создаем поверхность
    void createSurface() {
        if (glfwCreateWindowSurface(instance, window, nullptr, &surface) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать поверхность для рисования!");
        }
    }
    // проверка поддержки цепочки буферов
    SwapChainSupportDetails querySwapChainSupport(VkPhysicalDevice device) {
        SwapChainSupportDetails details;

        // проверяем поддерживаемые возможности
        vkGetPhysicalDeviceSurfaceCapabilitiesKHR(device, surface, &details.capabilities);

        uint32_t formatCount;
        // сначала получаем количество поддерживаемых форматов
        vkGetPhysicalDeviceSurfaceFormatsKHR(device, surface, &formatCount, nullptr);

        if (formatCount != 0) {
            details.formats.resize(formatCount); // расширяем вектор, чтобы вместить все данные
            // получаем все поддерживаемые форматы
            vkGetPhysicalDeviceSurfaceFormatsKHR(device, surface, &formatCount, details.formats.data());
        }

        uint32_t presentModeCount;
        // получаем количество поддерживаемых режимов представления
        vkGetPhysicalDeviceSurfacePresentModesKHR(device, surface, &presentModeCount, nullptr);

        if (presentModeCount != 0) {
            details.presentModes.resize(presentModeCount); 
            // получаем все поддерживаемые режимы представления
            vkGetPhysicalDeviceSurfacePresentModesKHR(device, surface, &presentModeCount, details.presentModes.data());
        }

        return details;
    }
    // выбираем физическое устройство
    void selectPhysicalDevice() {
        uint32_t deviceCount = 0;
        vkEnumeratePhysicalDevices(instance, &deviceCount, nullptr);

        if (deviceCount == 0) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }

        std::vector<VkPhysicalDevice> devices(deviceCount);
        vkEnumeratePhysicalDevices(instance, &deviceCount, devices.data());

        // выбираем первое подходящее устройство
        for (const auto& device : devices) {
            if (isDeviceSuitable(device)) {
                physicalDevice = device;
                break;
            }
        }

        if (physicalDevice == VK_NULL_HANDLE) {
            throw std::runtime_error("Подходящее устройство GPU отсутствует!");
        }
    }

    // создание логического устройства
    void createLogicalDevice() {
        // получаем обе очереди
        QueueFamilyIndices indices = findQueueFamilies(physicalDevice);

        std::vector<VkDeviceQueueCreateInfo> queueCreateInfos;
        // набор для индексов семейств очередей, если они совпадают, то остается только один индекс
        std::set<uint32_t> uniqueQueueFamilies = {
            indices.graphicsFamilyIndex,
            indices.presentFamilyIndex
        };

        float queuePriority = 1.0f;
        // проходим по всем индексам семейств очередей и создаем для каждого индекса структуру VkDeviceQueueCreateInfo
        for (uint32_t queueFamily : uniqueQueueFamilies) {
            VkDeviceQueueCreateInfo queueCreateInfo{};
            queueCreateInfo.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
            queueCreateInfo.queueFamilyIndex = queueFamily;
            queueCreateInfo.queueCount = 1;
            queueCreateInfo.pQueuePriorities = &queuePriority;
            queueCreateInfos.push_back(queueCreateInfo);
        }

        VkDeviceCreateInfo createInfo{};
        createInfo.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;

        // устанавливаем обе очереди для создания устройства
        createInfo.queueCreateInfoCount = static_cast<uint32_t>(queueCreateInfos.size());
        createInfo.pQueueCreateInfos = queueCreateInfos.data();
        
        // подключаемые расширения
        const std::vector<const char*> deviceExtensions = { VK_KHR_SWAPCHAIN_EXTENSION_NAME};
        // подключаем расширения 
        // устанавливаем количество расширений
        createInfo.enabledExtensionCount = static_cast<uint32_t>(deviceExtensions.size()); 
        // устанавливаем сами расширения
        createInfo.ppEnabledExtensionNames = deviceExtensions.data();

        // устанавливаем поддерживаемые возможности
        VkPhysicalDeviceFeatures deviceFeatures{};
        createInfo.pEnabledFeatures = &deviceFeatures;

        // создаем логическое устройство
        if (vkCreateDevice(physicalDevice, &createInfo, nullptr, &device) != VK_SUCCESS) {
            throw std::runtime_error("Не удалось создать логическое устройство!");
        }

        // создаем графическую очередь
        vkGetDeviceQueue(device, indices.graphicsFamilyIndex, 0, &graphicsQueue);
        // создаем очередь представления
        vkGetDeviceQueue(device, indices.presentFamilyIndex, 0, &presentQueue);
    }

    // проверяем поддержку цепочки буферов
    bool checkSwapchainExtensionSupport(VkPhysicalDevice device) {
        uint32_t extensionCount;
        // сначала получаем количество расширений
        vkEnumerateDeviceExtensionProperties(device, nullptr, &extensionCount, nullptr);

        // получаем все доступные расширения
        std::vector<VkExtensionProperties> availableExtensions(extensionCount);
        vkEnumerateDeviceExtensionProperties(device, nullptr, &extensionCount, availableExtensions.data());

        std::string extensionName {VK_KHR_SWAPCHAIN_EXTENSION_NAME}; // строка, с которой сравниванием

        for (const auto& extension : availableExtensions) {
            // сравнение строк
            if(extensionName == extension.extensionName) return true;
        }

        return false;
    }
   // проверка, является ли устройство подходящим
    bool isDeviceSuitable(VkPhysicalDevice device) {
        // получаем индексы графической очереди и очереди представления
        QueueFamilyIndices indices = findQueueFamilies(device);
        // если не поддерживаются графическая очередь и/или очередь представления
        if(!indices.isComplete()) return false; 
        // если не поддерживаются расширения
        if(!checkSwapchainExtensionSupport(device)) return false;
        // получаем поддержку цепочки буферов
        SwapChainSupportDetails swapChainSupport = querySwapChainSupport(device);
        // считаем устройство подходящим, если поддерживается хотя бы один формат и хотя бы один режим представления
        return !swapChainSupport.formats.empty() && !swapChainSupport.presentModes.empty();
    }
    // получаем индексы семейства очередей
    QueueFamilyIndices findQueueFamilies(VkPhysicalDevice device) {
        QueueFamilyIndices indices;

        uint32_t queueFamilyCount = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, nullptr);

        std::vector<VkQueueFamilyProperties> queueFamilies(queueFamilyCount);
        vkGetPhysicalDeviceQueueFamilyProperties(device, &queueFamilyCount, queueFamilies.data());

        int i = 0;
        // проходим по всем очередям
        for (const auto& queueFamily : queueFamilies) {
            // получаем индекс семейства с графической очередью
            if (queueFamily.queueFlags & VK_QUEUE_GRAPHICS_BIT) {
                indices.graphicsFamilyIndex = i;
                indices.graphicsSupport = true;
            }
            // смотрим, поддерживается ли очередь представления
            vkGetPhysicalDeviceSurfaceSupportKHR(device, i, surface, &indices.presentSupport);
            if (indices.presentSupport)  indices.presentFamilyIndex = i;
            if (indices.isComplete())  break; // если обе очереди установлены
            i++;
        }
        return indices;
    }
};

int main() {
    HelloApplication app;

    try {
        app.run();
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```



Рассмотрим основные моменты. Прежде всего для проверки возможностей поверхности рисования определена дополнительная структура:



```cpp

struct SwapChainSupportDetails {
    VkSurfaceCapabilitiesKHR capabilities;              // возможности поверхности
    std::vector<VkSurfaceFormatKHR> formats;      // доступные форматы
    std::vector<VkPresentModeKHR> presentModes;   // доступные режимы представления
};
```






В класс HelloApplication определена добавлена функция `querySwapChainSupport()`, которая получает физическое устройства и проверяет его поддерживаемые возможности, форматы и режимы представления:



```cpp

SwapChainSupportDetails querySwapChainSupport(VkPhysicalDevice device) {
    SwapChainSupportDetails details;

    // проверяем поддерживаемые возможности
    vkGetPhysicalDeviceSurfaceCapabilitiesKHR(device, surface, &details.capabilities);

    uint32_t formatCount;
    // сначала получаем количество поддерживаемых форматов
    vkGetPhysicalDeviceSurfaceFormatsKHR(device, surface, &formatCount, nullptr);

    if (formatCount != 0) {
        details.formats.resize(formatCount); // расширяем вектор, чтобы вместить все данные
        // получаем все поддерживаемые форматы
        vkGetPhysicalDeviceSurfaceFormatsKHR(device, surface, &formatCount, details.formats.data());
    }

    uint32_t presentModeCount;
    // получаем количество поддерживаемых режимов представления
    vkGetPhysicalDeviceSurfacePresentModesKHR(device, surface, &presentModeCount, nullptr);

    if (presentModeCount != 0) {
        details.presentModes.resize(presentModeCount); 
        // получаем все поддерживаемые режимы представления
        vkGetPhysicalDeviceSurfacePresentModesKHR(device, surface, &presentModeCount, details.presentModes.data());
    }

    return details;
}
```



Все данные для более простого управления обертываются в структуру SwapChainSupportDetails.



Кроме того, в классе определена функция checkSwapchainExtensionSupport для проверки поддержки цепочки буферов - расширения "VK_KHR_SWAPCHAIN_EXTENSION_NAME":



```cpp

